$ErrorActionPreference='Stop';$ScriptDir=Split-Path -Parent $MyInvocation.MyCommand.Path;. (Join-Path (Split-Path -Parent $ScriptDir) 'lib/common.ps1')
if(Test-Command buf){Write-Ok "buf $(& buf --version) ya instalado";exit 0};if(-not(Test-Command winget)){throw 'winget no disponible'};try{& winget install --id Bufbuild.Buf --silent --accept-package-agreements --accept-source-agreements}catch{if(Test-Command scoop){& scoop install buf}else{throw 'No se pudo instalar buf con winget y Scoop no está disponible'}};$machine=[Environment]::GetEnvironmentVariable('PATH','Machine');$user=[Environment]::GetEnvironmentVariable('PATH','User');$env:PATH="$machine;$user";if(-not(Test-Command buf)){throw 'buf no disponible tras instalación'};Write-Ok "buf $(& buf --version)"
